using Polly;
using Polly.CircuitBreaker;

var circuitBreaker = Policy
    .Handle<HttpRequestException>()
    .OrResult<string>(r => !r.IsSuccessStatusCode)
    .AdvancedCircuitBreakerAsync(
        failureThreshold: 0.5, // 50% failure rate
        samplingDuration: TimeSpan.FromSeconds(30),
        minimumThroughput: 10, // Minimum 10 requests
        durationOfBreak: TimeSpan.FromSeconds(60));

// Usage
var result = await circuitBreaker.ExecuteAsync(async () => {
    return await httpClient.GetAsync("https://payment-service/health");
});

// Circuit breaker states:
// Closed -> Open (after 50% failures in 30s)
// Open -> HalfOpen (after 60s timeout)
// HalfOpen -> Closed (success) or Open (failure)
